IDS = ["WHY-037","WHY-038","WHY-039","WHY-040","WHY-041","WHY-042","WHY-043","WHY-044","WHY-068","WHY-069","GSZ-107","GSZ-108","GSZ-109","GSZ-110"]
assert len(CASES) == 14, len(CASES)
assert [c["case_id"] for c in CASES] == IDS
total = 0
for c in CASES:
    assert set(c.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, c["case_id"]
    assert 0.0 <= c["confidence"] <= 1.0
    t = c["trigger"]
    assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}
    for k in ("changed_main","reserve_used","disputed"):
        assert isinstance(t[k], bool), (c["case_id"], k)
    assert c["basis"].split("\n")[0] == "liuyao"
    p = os.path.join(OUT, c["case_id"] + ".json")
    data = json.dumps(c, ensure_ascii=False, indent=2).encode("utf-8")
    with open(p, "wb") as f:
        f.write(data)
    total += len(data)
    with open(p, encoding="utf-8") as f:
        back = json.load(f)
    assert back["case_id"] == c["case_id"]
print("written", len(CASES), "total_bytes", total)
print("changed_main", sum(1 for c in CASES if c["trigger"]["changed_main"]))
print("reserve_used", sum(1 for c in CASES if c["trigger"]["reserve_used"]))
